window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[322]={"id":"322","numero":322,"titre":"Décision thérapeutique personnalisée","objectifs":[{"id":"322-1","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'adaptation thérapeutique chez l’obèse","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>322-decision-therapeutique-personnalise/</code> classent ce point comme « non fiché, peu tombable » : aucun contenu détaillé sur l'adaptation thérapeutique chez l'obèse n'y figure. Kevin enrichira ce paragraphe (Collège de Thérapeutique, ou recherche ciblée).\n      </div>\n      <!-- TODO Kevin : adaptation posologique chez l'obèse — volume de distribution des molécules lipophiles, choix poids total / poids idéal / poids ajusté selon la molécule -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 253 — <span class=\"kw-etio\">Obésité</span></em></p>","frequence":0},{"id":"322-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'adaptation thérapeutique chez l'enfant","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Point classé « non fiché, peu tombable » dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>322-decision-therapeutique-personnalise/</code>. Aucun contenu détaillé sur l'adaptation thérapeutique chez l'enfant n'y figure. Kevin enrichira ce paragraphe.\n      </div>\n      <!-- TODO Kevin : adaptation posologique pédiatrique — posologie au poids / surface corporelle, formes galéniques adaptées, médicaments contre-indiqués chez l'enfant -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":0},{"id":"322-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'adaptation thérapeutique pendant la grossesse et l'allaitement","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Point classé « non fiché, peu tombable » dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>322-decision-therapeutique-personnalise/</code>. Aucun contenu détaillé sur l'adaptation thérapeutique pendant la <span class=\"kw-ci\">grossesse</span> et l'allaitement n'y figure. Kevin enrichira ce paragraphe (ressource CRAT — Centre de Référence sur les Agents Tératogènes).\n      </div>\n      <!-- TODO Kevin : grossesse — tératogénicité par trimestre, médicaments CI, CRAT ; allaitement — passage dans le lait -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale</em></p>","frequence":0},{"id":"322-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'adaptation thérapeutique chez la personne âgée (voir item 130)","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Point classé « non fiché, peu tombable » dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>322-decision-therapeutique-personnalise/</code>. Aucun contenu détaillé sur l'adaptation thérapeutique chez la personne âgée n'y figure. Kevin enrichira ce paragraphe (item 130 — prescription chez le sujet âgé : baisse physiologique du <span class=\"kw-bio\">DFG</span>, polymédication, cascade <span class=\"kw-etio\">iatrogène</span>, critères STOPP/START, déprescription).\n      </div>\n      <!-- TODO Kevin : sujet âgé — <span class=\"kw-bio\"><span class=\"kw-bio\">DFG</span></span>, polymédication, déprescription, critères STOPP/START -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 133 — Autonomie-dépendance du sujet âgé · 325 — Risque <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-etio\">iatrogène</span></em></p>","frequence":1},{"id":"322-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'adaptation thérapeutique chez l'insuffisant rénal","contenu":"<p>L'<span class=\"kw-ci\">insuffisance rénale</span> (IR) modifie l'effet des médicaments à <strong>plusieurs étages de la pharmacocinétique</strong>, pas seulement l'élimination rénale.</p>\n      <table >\n        <thead><tr><th>Étape PK</th><th>Effet de l'insuffisance rénale</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Biodisponibilité</strong></td><td>Modification du <span class=\"kw-def\">pH gastrique</span> et ralentissement du transit → absorption <span class=\"kw-chiffre\">diminuée ou retardée</span>.</td></tr>\n          <tr><td><strong>Distribution</strong></td><td><strong><span class=\"kw-clinique\">Œdèmes</span> :</strong> augmentation du volume de distribution<br><strong><span class=\"kw-clinique\">Déshydratation</span> / fonte musculaire :</strong> baisse du V<sub>d</sub> → concentration augmentée<br><strong>Liaison protéique :</strong> hypoalbuminémie et <span class=\"kw-def\">toxines urémiques</span> <span class=\"kw-alerte\">augmentent la fraction libre</span> active</td></tr>\n          <tr><td><strong>Élimination hépatique</strong></td><td><span class=\"kw-clinique\">Les</span> toxines urémiques altèrent les activités enzymatiques (cytochromes, glucuronidation, acétylation).</td></tr>\n          <tr><td><strong>Élimination rénale</strong></td><td>Combinaison d'un défaut de <span class=\"kw-bio\">filtration glomérulaire</span> et d'une altération des <span class=\"kw-bio\">transporteurs tubulaires</span> (compétition avec <span class=\"kw-clinique\">les</span> toxines urémiques).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> L'altération des fonctions tubulaires <span class=\"kw-alerte\">n'est pas proportionnelle au DFG</span> : prédire le comportement d'un médicament d'après le seul <span class=\"kw-bio\">DFG</span> estimé est hasardeux.\n      </div>\n      <h4>Médicaments néphrotoxiques par classe</h4>\n      <p><em>NTA : <span class=\"kw-clinique\">nécrose</span> tubulaire aiguë ; NIA : néphrite interstitielle aiguë ; MAT : microangiopathie <span class=\"kw-etio\">thrombotique</span>.</em></p>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécules et type d'atteinte</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antibiotiques</strong></td><td><span class=\"kw-ttt\">Aminosides</span> (NTA) ; <span class=\"kw-ttt\">ciprofloxacine</span> (NIA, précipitation) ; <span class=\"kw-ttt\">β-lactamines</span> (NIA immuno-<span class=\"kw-etio\">allergique</span>)</td></tr>\n          <tr><td><strong>Antiviraux</strong></td><td><span class=\"kw-ttt\">Ténofovir</span>, <span class=\"kw-ttt\">cidofovir</span>, <span class=\"kw-ttt\">adéfovir</span>, <span class=\"kw-ttt\">aciclovir</span>, <span class=\"kw-ttt\">indinavir</span> (NTA)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Antifongique</span></strong></td><td><span class=\"kw-ttt\">Amphotéricine B</span> (NTA)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chimiothérapie</span></strong></td><td><span class=\"kw-ttt\">Sels de platine</span>, <span class=\"kw-ttt\">méthotrexate</span> (NTA) ; <span class=\"kw-ttt\">ifosfamide</span> (tubulopathie, <span class=\"kw-def\">IRA</span>) ; <span class=\"kw-ttt\">mitomycine C</span>, <span class=\"kw-ttt\">gemcitabine</span> (MAT)</td></tr>\n          <tr><td><strong>Thérapies ciblées / immunothérapies</strong></td><td>Anti-angiogéniques et inhibiteurs de tyrosine kinase (MAT) ; <span class=\"kw-ttt\">interférons</span> (MAT) ; inhibiteurs de checkpoint anti-CTLA-4 / anti-PD-1 (néphrite tubulo-interstitielle)</td></tr>\n          <tr><td><strong>Analgésiques</strong></td><td><span class=\"kw-ttt\">AINS</span> : perturbation de l'hémodynamique rénale, NIA immuno-<span class=\"kw-etio\">allergique</span>, glomérulopathie</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Immunosuppresseurs</span></strong></td><td><span class=\"kw-ttt\">Ciclosporine</span>, <span class=\"kw-ttt\">tacrolimus</span> (toxicité vasculaire, NTA) ; inhibiteurs de mTOR (NTA)</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-ttt\">Produits de contraste iodés</span> (NTA) ; <span class=\"kw-ttt\">lithium</span> (NTA, IR chronique) ; <span class=\"kw-ttt\">IPP</span> (NIA, IR chronique) ; <span class=\"kw-ttt\">biphosphonates</span> ; <span class=\"kw-ttt\">IEC/ARA2</span> et <span class=\"kw-ttt\">diurétiques</span> (toxicité <strong>indirecte</strong> : hémodynamique rénale, <span class=\"kw-clinique\">déshydratation</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4>Évaluer puis adapter</h4>\n      <ul>\n        <li><strong>Évaluation :</strong> clinique (poids, volume extra-cellulaire) + estimation du <span class=\"kw-bio\">DFG</span>. <span class=\"kw-bio\">CKD-EPI</span> = formule de référence ; <span class=\"kw-bio\">Cockcroft-Gault</span> = seule formule citée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">RCP</span>, donc encore utilisée pour l'adaptation des posologies.</li>\n        <li><strong>Adaptation de la dose :</strong> diminuer <span class=\"kw-clinique\">les</span> doses (si index thérapeutique étroit + demi-vie courte), ou les espacer (si demi-vie longue + index large), ou les deux.</li>\n        <li><strong><span class=\"kw-def\">IRA</span> :</strong> pas de mesure simple et fiable de la fonction rénale (<span class=\"kw-bio\">créatinine</span> = marqueur retardé) → privilégier le <span class=\"kw-bio\">monitorage des concentrations plasmatiques</span> quand il est disponible.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Prévention de la néphrotoxicité.</strong> Mesure préalable de la fonction rénale ; correction d'une hypovolémie et des troubles électrolytiques ; adaptation des doses ; <span class=\"kw-def\">surveillance</span> (fonction rénale, sédiment urinaire, taux plasmatiques) ; réévaluation régulière de la pertinence de la prescription.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":2},{"id":"322-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","contenu":"<p>Le foie assure la <strong>biotransformation</strong> des médicaments liposolubles en métabolites hydrosolubles éliminables, en deux phases :</p>\n      <ul>\n        <li><strong>Phase I :</strong> oxydation par le système des <span class=\"kw-def\">cytochromes P450</span> → métabolites intermédiaires (parfois réactifs et toxiques).</li>\n        <li><strong>Phase II :</strong> conjugaison / acétylation → métabolites polaires, hydrosolubles.</li>\n      </ul>\n      <p>En cas d'<strong><span class=\"kw-alerte\">insuffisance hépatocellulaire</span> (<span class=\"kw-bio\">IHC</span>)</strong> ou d'<strong><span class=\"kw-clinique\">hypertension</span> portale</strong>, plusieurs paramètres sont modifiés :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Effet de 1<sup>er</sup> passage hépatique</strong></td><td>Baisse du débit sanguin hépatique + shunt porto-cave → <span class=\"kw-alerte\">concentration augmentée</span> des médicaments à fort 1<sup>er</sup> passage → réduire la posologie.</td></tr>\n          <tr><td><strong>Prodrogues</strong></td><td>Activation hépatique altérée → <span class=\"kw-alerte\">perte d'efficacité</span>.</td></tr>\n          <tr><td><strong>Liaison protéique</strong></td><td>Baisse de synthèse de l'<span class=\"kw-bio\">albumine</span> → augmentation de la fraction libre et de l'effet des médicaments fortement liés.</td></tr>\n          <tr><td><strong>Déplétion en glutathion</strong></td><td>Dénutrition + <span class=\"kw-bio\">IHC</span> → défense antioxydante altérée → <span class=\"kw-alerte\">hépatotoxicité majorée</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> tests hépatiques usuels <span class=\"kw-alerte\">ne préjugent pas</span> des capacités d'extraction et de métabolisme du foie. En cas de doute, monitorer les médicaments à <span class=\"kw-def\">marge thérapeutique étroite</span>.\n      </div>\n      <h4>Médicaments hépatotoxiques</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fort 1<sup>er</sup> passage hépatique</strong><br>(posologie à réduire si <span class=\"kw-def\">cirrhose</span>)</td><td><span class=\"kw-ttt\">Antagonistes calciques</span>, <span class=\"kw-ttt\">β-bloquants</span>, <span class=\"kw-ttt\">statines</span>, <span class=\"kw-ttt\">morphine</span>, <span class=\"kw-ttt\">sumatriptan</span>, antidépresseurs, antipsychotiques, anxiolytiques, hypnotiques, antiparkinsoniens</td></tr>\n          <tr><td><strong>Hépatotoxicité élevée</strong><br>si hépatopathie fibrosante</td><td><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">antituberculeux</span>, <span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">valproate</span>, <span class=\"kw-ttt\">vitamine A</span>, antiviraux anti-<span class=\"kw-etio\">VIH</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Prescrire chez l'hépatopathe</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">IHC</span> aiguë ictérique</strong></td><td><span class=\"kw-alerte\">Arrêt de toute médication non vitale</span> = règle. Si <span class=\"kw-ttt\">anticoagulation</span> nécessaire : remplacer <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AVK</span> par l'<span class=\"kw-ttt\">héparine</span> pendant l'épisode.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Cirrhose</span> avec <span class=\"kw-bio\">IHC</span></strong></td><td><span class=\"kw-ci\">AINS contre-indiqués</span> quel que soit le degré d'<span class=\"kw-bio\">IHC</span> ; <span class=\"kw-ci\">aminosides CI si ictère</span> ; <span class=\"kw-ci\">colchicine CI</span> (<span class=\"kw-def\">hépatite</span> aiguë, <span class=\"kw-def\">cirrhose</span> Child B et C) ; sérum glucosé CI avant injection de B1 si dénutrition.</td></tr>\n          <tr><td><strong>Hépatopathie chronique sans <span class=\"kw-bio\">IHC</span></strong></td><td><span class=\"kw-ci\">AINS CI</span> si <span class=\"kw-def\">hépatite</span> chronique fibrosante (même sans <span class=\"kw-bio\">IHC</span> ni <span class=\"kw-clinique\">HTP</span>) ; éviter la vitamine A ; <span class=\"kw-ci\"><span class=\"kw-def\">surveillance</span> hépatique</span> serrée sous <span class=\"kw-ttt\">azathioprine</span>, antituberculeux, <span class=\"kw-ttt\">antirétroviraux</span>.</td></tr>\n          <tr><td><strong>Tumeurs bénignes du foie</strong><br>(adénome, adénomatose)</td><td><span class=\"kw-ci\">Œstrogènes, androgènes et stéroïdes anabolisants contre-indiqués</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Si un médicament hépatotoxique est indispensable, préférer ceux responsables d'hépatites <span class=\"kw-def\">cholestatiques</span> plutôt que <span class=\"kw-def\">cytolytiques</span>. Hors foie, <span class=\"kw-clinique\">les</span> organes les plus sensibles à l'iatrogénie chez le cirrhotique sont le tube digestif, le cerveau et le rein.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span></em></p>","frequence":1},{"id":"322-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d’une décision médicale partagée avec un malade et son entourage (voir item 3)","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>322-decision-therapeutique-personnalise/</code>. La décision médicale partagée est traitée dans l'item 3 (Raisonnement et décision en médecine). Kevin enrichira ce paragraphe : information loyale, claire et adaptée ; recueil des préférences du patient et de son entourage ; consentement éclairé ; balance bénéfice/risque expliquée.\n      </div>\n      <!-- TODO Kevin : décision médicale partagée — étapes, place de l'entourage, lien avec l'item 3 -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 3 — Raisonnement et décision en médecine</em></p>","frequence":0},{"id":"322-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prescription médicamenteuse, les modalités de surveillance et d’arrêt","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>322-decision-therapeutique-personnalise/</code> ne détaillent pas cet objectif de façon dédiée. Kevin enrichira ce paragraphe depuis les items 326 et 330 : principes de la prescription (indication validée, balance bénéfice/risque, respect de l'AMM/<span class=\"kw-def\">RCP</span>), modalités de <span class=\"kw-def\">surveillance</span> (efficacité, tolérance, observance, dosages plasmatiques si marge étroite) et modalités d'arrêt (réévaluation régulière, déprescription, arrêt progressif si risque de rebond ou de <span class=\"kw-ttt\">sevrage</span>).\n      </div>\n      <!-- TODO Kevin : prescription / surveillance / arrêt — à rédiger depuis les items 326 et 330 -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription et reco pour bon usage · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 325 — Risque <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-etio\">iatrogène</span></em></p>","frequence":1},{"id":"322-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la consultation pré-anesthésique","contenu":"<p>La consultation pré-anesthésique précède tout geste programmé sous anesthésie. <span class=\"kw-clinique\">Les</span> fiches sources n'en détaillent que le volet <strong>examens complémentaires</strong> :</p>\n      <div class=\"callout callout-info\">\n        <strong>Règle.</strong> <span class=\"kw-alerte\">Aucun examen complémentaire n'est systématique</span> avant un geste invasif ou chirurgical, avec ou sans anesthésie générale.\n      </div>\n      <p>La prescription d'un bilan pré-interventionnel est <strong>raisonnée, rationnelle et individualisée</strong>, selon :</p>\n      <ul>\n        <li>le <strong>type de geste</strong> envisagé ;</li>\n        <li>le <strong>risque <span class=\"kw-etio\">hémorragique</span></strong> ;</li>\n        <li><span class=\"kw-clinique\">les</span> <strong>antécédents</strong> et les <strong>traitements</strong> du patient.</li>\n      </ul>\n      <p>Exemple : un geste à faible risque <span class=\"kw-etio\">hémorragique</span> chez un patient jeune, sans traitement interférant avec l'hémostase et sans <span class=\"kw-clinique\">diathèse hémorragique</span> personnelle ou familiale ne nécessite <span class=\"kw-clinique\">aucun examen complémentaire</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> autres principes de la consultation pré-anesthésique (délai légal de réalisation, évaluation du <span class=\"kw-def\">score ASA</span>, recherche de critères d'<span class=\"kw-ttt\">intubation</span> difficile, information et consentement) ne figurent pas dans les fiches sources — Kevin les ajoutera depuis le référentiel d'anesthésie.\n      </div>\n      <!-- TODO Kevin : consultation pré-anesthésique — délai réglementaire, <span class=\"kw-def\"><span class=\"kw-def\">score</span> ASA</span>, critères d'intubation difficile -->","frequence":0},{"id":"322-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du jeûne pré-anesthésie","contenu":"<p>Le <strong>jeûne pré-opératoire</strong> est requis avant tout acte programmé sous anesthésie — <strong>générale comme loco-régionale</strong> (une ALR peut toujours basculer en AG).</p>\n      <div class=\"callout callout-info\">\n        <strong>Objectif.</strong> Éviter l'<span class=\"kw-alerte\">inhalation bronchique du contenu gastrique</span> lors du contrôle des voies aériennes supérieures et de la ventilation artificielle.\n      </div>\n      <h4>Durées de jeûne chez l'adulte</h4>\n      <table >\n        <thead><tr><th>Apport</th><th>Délai avant l'acte</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Solides</strong> (repas léger)</td><td><span class=\"kw-chiffre\">6 h</span></td></tr>\n          <tr><td><strong>Liquides clairs</strong> (eau, thé, café, jus sans pulpe)</td><td><span class=\"kw-chiffre\">2 h</span></td></tr>\n          <tr><td><strong>Traitements per os habituels</strong></td><td><span class=\"kw-chiffre\">2 h</span> (avec un verre d'eau le matin de l'intervention — sauf médicaments à risque, antithrombotiques notamment)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Tabac</span></strong></td><td><span class=\"kw-chiffre\">≥ 2 h</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Pièges.</strong><br>\n        Même après un jeûne parfaitement respecté, l'inhalation reste possible en cas de <span class=\"kw-alerte\">RGO sévère</span> ou de pathologie gastro-œsophagienne.<br>\n        Il n'est <span class=\"kw-alerte\">pas</span> possible de sucer un bonbon ni de mâcher un chewing-gum juste avant l'intervention.\n      </div>","frequence":0},{"id":"322-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","contenu":"<p>La gestion péri-opératoire des traitements est <strong>pluridisciplinaire</strong> (anesthésiste, chirurgien, cardiologue…). Elle arbitre en permanence entre <span class=\"kw-alerte\">risque hémorragique</span> du geste et <span class=\"kw-alerte\">risque thrombotique</span> du patient.</p>\n      <table >\n        <thead><tr><th>Traitement</th><th>Risque en cas de poursuite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Antiagrégants</span> plaquettaires, anticoagulants</strong></td><td>Risque <span class=\"kw-alerte\">hémorragique</span></td></tr>\n          <tr><td><strong>Antagonistes du SRA</strong></td><td>Majoration du risque d'<span class=\"kw-alerte\">hypotension artérielle</span> sous AG</td></tr>\n          <tr><td><strong>Biguanides</strong></td><td>Risque d'<span class=\"kw-alerte\">acidose lactique</span></td></tr>\n          <tr><td><strong>Sulfamides, <span class=\"kw-ttt\">glinides</span></strong></td><td>Risque d'<span class=\"kw-alerte\">hypoglycémie</span> pendant le jeûne pré-interventionnel</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Corticothérapie</span> au long cours</strong></td><td>Risque d'<span class=\"kw-alerte\">insuffisance surrénalienne aiguë</span></td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-ttt\">Antiagrégants</span> plaquettaires (AAP)</h4>\n      <ul>\n        <li><strong>Monothérapie :</strong> la majorité des gestes sont réalisables sous <span class=\"kw-ttt\">aspirine</span> à dose antiagrégante. Si <span class=\"kw-ttt\">clopidogrel</span> en monothérapie chez un coronarien → faire un <strong>relais par l'<span class=\"kw-ttt\">aspirine</span></strong>. Certains gestes imposent l'arrêt de l'<span class=\"kw-ttt\">aspirine</span> : <span class=\"kw-ttt\">chirurgie</span> <span class=\"kw-alerte\">ORL, urologique, neurologique</span>.</li>\n        <li><strong>Bithérapie</strong> (AAS + <span class=\"kw-ttt\">clopidogrel</span> / <span class=\"kw-ttt\">ticagrelor</span> / <span class=\"kw-ttt\">prasugrel</span>) : la majorité des gestes ne sont pas réalisables sous bi-antiagrégation. Après <span class=\"kw-ttt\">stent</span>, retarder tout acte non urgent : <span class=\"kw-chiffre\">≥ 6 semaines</span> si stent nu, <span class=\"kw-chiffre\">3 à 6 mois</span> si stent actif (<span class=\"kw-alerte\">risque majeur de thrombose de stent</span>). Si l'acte ne peut être différé : <strong><span class=\"kw-ttt\">aspirine</span> toujours maintenue</strong>, arrêt le plus court possible de l'inhibiteur du P2Y12.</li>\n        <li><strong><span class=\"kw-imagerie\">Endoscopie</span> :</strong> <span class=\"kw-imagerie\">endoscopie</span> digestive ± <span class=\"kw-bio\">biopsie</span> possible sous bi-antiagrégation ; <span class=\"kw-imagerie\">endoscopie</span> bronchique avec <span class=\"kw-bio\">biopsies</span> possible sous <span class=\"kw-ttt\">aspirine</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Règle des 3-5-7</strong> — délai d'arrêt avant l'acte quand un arrêt est nécessaire : <span class=\"kw-chiffre\">aspirine 3 j</span> (5 j si neurochirurgie intracrânienne / ORL) ; <span class=\"kw-chiffre\">clopidogrel et ticagrelor 5 j</span> ; <span class=\"kw-chiffre\">prasugrel 7 j</span>.\n      </div>\n      <h4>Antivitamines K (<span class=\"kw-ttt\">AVK</span>)</h4>\n      <table >\n        <thead><tr><th>Risque thrombo-<span class=\"kw-etio\">embolique</span></th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Faible</strong><br>(FA sans ATCD <span class=\"kw-etio\">embolique</span>, MTEV à risque modéré)</td><td>Arrêt de l'<span class=\"kw-ttt\">AVK</span> <span class=\"kw-chiffre\">3 à 4 j</span> avant, <span class=\"kw-alerte\">sans relais</span>, pour normaliser l'<span class=\"kw-bio\">INR</span> ; reprise le soir même ou dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24-48 h</span>.</td></tr>\n          <tr><td><strong>Élevé</strong><br>(valve mécanique, FA avec ATCD <span class=\"kw-etio\">embolique</span>, MTEV à haut risque)</td><td>Arrêt <span class=\"kw-chiffre\">4 à 5 j</span> avant + <strong>relais pré-opératoire par <span class=\"kw-ttt\">héparine</span> à dose curative</strong> ; reprise de l'<span class=\"kw-ttt\">héparine</span> <span class=\"kw-chiffre\">6 h après</span> le geste (jamais avant) ; relais <span class=\"kw-ttt\">héparine</span> → <span class=\"kw-ttt\">AVK</span> ensuite.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ci\">AINS sont contre-indiqués</span> en post-opératoire chez un patient sous <span class=\"kw-ttt\">AVK</span>. Objectif <span class=\"kw-chiffre\">INR &lt; 1,5</span> le jour de l'acte quand un arrêt est nécessaire.\n      </div>\n      <h4><span class=\"kw-ttt\">Anticoagulants</span> oraux directs (<span class=\"kw-ttt\">AOD</span>)</h4>\n      <ul>\n        <li>Gestion calquée sur celle des <span class=\"kw-ttt\">AVK</span>, mais <span class=\"kw-alerte\">sans relais héparine</span> chez le patient à haut risque thrombo-<span class=\"kw-etio\">embolique</span> (surrisque <span class=\"kw-etio\">hémorragique</span>).</li>\n        <li><strong>Faible risque <span class=\"kw-etio\">hémorragique</span> :</strong> pas de prise la veille au soir ni le matin de l'intervention ; reprise <span class=\"kw-chiffre\">≥ 6 h</span> après.</li>\n        <li><strong>Risque <span class=\"kw-etio\">hémorragique</span> élevé :</strong> dernière prise à <span class=\"kw-chiffre\">J-3</span> (xabans) ou <span class=\"kw-chiffre\">J-4</span> (<span class=\"kw-ttt\">dabigatran</span>) ; <span class=\"kw-chiffre\">J-5</span> si très haut risque <span class=\"kw-etio\">hémorragique</span>, ou si IR modérée pour le <span class=\"kw-ttt\">dabigatran</span>. En post-op : <span class=\"kw-ttt\">anticoagulation</span> prophylactique <span class=\"kw-chiffre\">≥ 6 h</span> après, curative dès que l'hémostase le permet.</li>\n      </ul>\n      <h4>Autres médicaments</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Conduite péri-opératoire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Diurétiques</span></strong></td><td>Non pris le matin de l'intervention.</td></tr>\n          <tr><td><strong>SRAA à visée anti-<span class=\"kw-def\">HTA</span></strong></td><td><span class=\"kw-chiffre\">Arrêt 12-24 h avant</span> (risque d'<span class=\"kw-clinique\">hypotension</span> avec <span class=\"kw-clinique\">les</span> anesthésiants).</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Corticothérapie</span> au long cours</strong></td><td>Ne jamais arrêter brutalement. <span class=\"kw-ttt\">Opothérapie substitutive par hydrocortisone</span> :<span class=\"kw-chiffre\"> 25 à 75 mg</span> si <span class=\"kw-ttt\">chirurgie</span> mineure/modérée ;<span class=\"kw-chiffre\"> 50 mg</span> /<span class=\"kw-chiffre\"> 6 h</span> jusqu'à <span class=\"kw-chiffre\">H48</span>-72 si chirurgie majeure.</td></tr>\n          <tr><td><strong>Biguanides (<span class=\"kw-ttt\">metformine</span>)</strong></td><td><span class=\"kw-ttt\">Chirurgie</span> mineure sans produit de contraste : pas d'arrêt. Sinon : <span class=\"kw-chiffre\">arrêt 12-24 h avant</span>, reprise <span class=\"kw-chiffre\">48 h après</span> (si fonction rénale OK et reprise de l'alimentation).</td></tr>\n          <tr><td><strong>Sulfamides, <span class=\"kw-ttt\">glinides</span></strong></td><td>Arrêt la veille ou le matin si <span class=\"kw-ttt\">chirurgie</span> majeure (<span class=\"kw-alerte\">hypoglycémie</span> si poursuivis pendant le jeûne).</td></tr>\n          <tr><td><strong>Traitements maintenus</strong></td><td><span class=\"kw-ttt\">β-bloquants</span>, <span class=\"kw-ttt\">inhibiteurs calciques</span>, <span class=\"kw-ttt\">statines</span>, SRAA de l'<span class=\"kw-def\">insuffisance cardiaque</span> (risque de <span class=\"kw-alerte\">décompensation</span>) ; <span class=\"kw-ttt\">antiparkinsoniens</span>, <span class=\"kw-ttt\">psychotropes</span>, <span class=\"kw-ttt\">antiépileptiques</span> (risque de syndrome de <span class=\"kw-ttt\">sevrage</span>).</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":5},{"id":"322-12","rang":"B","rubrique":"Prise en charge","titre":"Dépendance médicamenteuse : connaître les indications et principes du sevrage médicamenteux (voir items 77, 78)","contenu":"<p><span class=\"kw-clinique\">Les</span> médicaments pouvant induire une <span class=\"kw-def\">dépendance</span> se répartissent en trois groupes selon leurs effets psychotropes :</p>\n      <ul>\n        <li><strong>Psycholeptiques :</strong> <span class=\"kw-ttt\">morphiniques</span> ; antihistaminiques à forte dose ; anticholinergiques à forte dose.</li>\n        <li><strong>Psychoanaleptiques (psychostimulants) :</strong> antidépresseurs anorexigènes ; <span class=\"kw-ttt\">anabolisants</span> ; anticholinergiques à faible dose.</li>\n        <li><strong>Psychodysleptiques (sédatifs) :</strong> <span class=\"kw-ttt\">benzodiazépines</span> ; <span class=\"kw-ttt\">barbituriques</span> ; antihistaminiques à faible dose.</li>\n      </ul>\n      <h4>Caractéristiques de la dépendance par classe</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Dépendance<br>physique / psychique</th><th>Tolérance</th><th><span class=\"kw-ttt\">Sevrage</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Benzodiazépines</strong></td><td>+++ / ++++</td><td>+</td><td>Oui</td></tr>\n          <tr><td><strong>Opiacés</strong></td><td>+++ / +++</td><td>+++</td><td>Oui</td></tr>\n          <tr><td><strong>Barbituriques</strong></td><td>+++ / +++</td><td>+++</td><td>Oui</td></tr>\n          <tr><td><strong>Anabolisants</strong></td><td>++ / +++</td><td>+++</td><td>Oui</td></tr>\n          <tr><td><strong>Anorexigènes</strong></td><td>o / +++</td><td>++</td><td>Oui</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Corticoïdes</span></strong></td><td>+ / +</td><td>o</td><td>Oui</td></tr>\n          <tr><td><strong>Antihistaminiques</strong></td><td>o / +++</td><td>o</td><td>Non</td></tr>\n          <tr><td><strong>Anticholinergiques</strong></td><td>o / +</td><td>o</td><td>Rare</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Principe du <span class=\"kw-ttt\">sevrage</span>.</strong> <span class=\"kw-clinique\">Les</span> substances à <span class=\"kw-clinique\">syndrome de sevrage</span> sévère (<span class=\"kw-ttt\">benzodiazépines</span>, <span class=\"kw-ttt\">barbituriques</span>, <span class=\"kw-ttt\">opiacés</span>) imposent un <span class=\"kw-alerte\">arrêt progressif</span>. La prévention repose sur une prescription contrôlée, de durée limitée, et un <span class=\"kw-def\">suivi</span> médical rigoureux.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 77 — Addiction aux psychotropes · 78 — Addication aux drogues</em></p>","frequence":0},{"id":"322-13","rang":"A","rubrique":"Prise en charge","titre":"Interactions médicamenteuses : identifier les principaux mécanismes d'interactions médicamenteuses","contenu":"<p>Le <strong>thésaurus de l'ANSM</strong> répertorie <span class=\"kw-clinique\">les</span> interactions à risque clinique et leur attribue un <span class=\"kw-def\">niveau de contrainte</span> :</p>\n      <table >\n        <thead><tr><th>Niveau de contrainte</th><th>Signification</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ci\">Contre-indication</span></td><td>L'association ne doit pas être prescrite.</td></tr>\n          <tr><td><strong>Association déconseillée</strong></td><td>À éviter sauf absence d'alternative ; <span class=\"kw-def\">surveillance</span> étroite du patient.</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Précaution d'emploi</span></strong></td><td>Association possible avec <span class=\"kw-def\">surveillance</span> renforcée (clinique, <span class=\"kw-ttt\">biologique</span>, <span class=\"kw-bio\">ECG</span>, concentrations plasmatiques) et adaptation des posologies.</td></tr>\n          <tr><td><strong>À prendre en compte</strong></td><td>Simple majoration d'un risque additif d'effets indésirables (effets sédatifs, atropiniques…).</td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-clinique\">Les</span> deux grands mécanismes</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Pharmacodynamique</strong></td><td>Médicaments agissant sur la <strong>même cible ou fonction</strong> — concentrations plasmatiques <span class=\"kw-chiffre\">inchangées</span>, interaction généralement <span class=\"kw-clinique\">prévisible</span> :<br><strong>Synergie :</strong> association d'antibiotiques ; plurithérapie de l'<span class=\"kw-def\">HTA</span><br><strong>Antagonisme :</strong> agoniste dopaminergique + neuroleptique ; <span class=\"kw-ttt\">AINS</span> réduisant l'effet des anti-<span class=\"kw-def\">HTA</span><br><strong>EI additifs :</strong> torsades de pointe ; médicaments hyperkaliémiants ; médicaments sérotoninergiques (IRSS, <span class=\"kw-ttt\">IMAO</span>, <span class=\"kw-ttt\">tramadol</span>, <span class=\"kw-ttt\">linézolide</span>)</td></tr>\n          <tr><td><strong>Pharmacocinétique</strong></td><td>Un médicament « B » modifie une étape PK du médicament « A » → concentration de « A » <span class=\"kw-alerte\">augmentée (toxicité)</span> ou <span class=\"kw-alerte\">diminuée (inefficacité)</span>. Étapes : absorption, liaison protéique, <strong>métabolisme (CYP450)</strong>, élimination rénale.</td></tr>\n        </tbody>\n      </table>\n      <h4>Cytochrome P450 : induction <span class=\"kw-bio\">vs</span> inhibition</h4>\n      <p>Le <span class=\"kw-def\">cytochrome P450</span> (exprimé dans <span class=\"kw-clinique\">les</span> entérocytes et le foie) catalyse ~<span class=\"kw-chiffre\">95 %</span> des oxydations de médicaments. Deux phénomènes opposés :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Induction enzymatique</th><th>Inhibition enzymatique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Effet sur le substrat</strong></td><td>Métabolisme accéléré → concentration <span class=\"kw-chiffre\">diminuée</span></td><td>Métabolisme ralenti → concentration <span class=\"kw-chiffre\">augmentée</span></td></tr>\n          <tr><td><strong>Risque</strong></td><td><span class=\"kw-alerte\">Inefficacité</span> (sous-dosage)</td><td><span class=\"kw-alerte\">Toxicité</span> (surdosage)</td></tr>\n          <tr><td><strong>Délai</strong></td><td>Retardé (<span class=\"kw-chiffre\">10-15 j</span>), réversible progressivement à l'arrêt de l'inducteur</td><td>Rapide</td></tr>\n          <tr><td><strong>Spécificité</strong></td><td>Peu spécifique (touche plusieurs CYP)</td><td>Spécifique d'un CYP donné</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège QCM.</strong> On <span class=\"kw-alerte\">n'augmente pas</span> la posologie d'un substrat parce qu'un inducteur a été introduit. <span class=\"kw-clinique\">Les</span> CAT correctes : remplacer une des deux molécules, ou adapter prudemment la dose du substrat — à la hausse à l'introduction de l'inducteur, à la baisse à son arrêt (inversement pour un inhibiteur).\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Pharmacogénétique.</strong> Le génotype module la PK/PD : <span class=\"kw-clinique\">les</span> patients <span class=\"kw-def\">métaboliseurs lents (PM)</span> ou <span class=\"kw-def\">ultra-rapides (UM)</span> sont à risque. Un génotypage est recommandé au <span class=\"kw-def\">RCP</span> avant certains traitements : <span class=\"kw-ttt\">abacavir</span> et <span class=\"kw-ttt\">carbamazépine</span> (allèle <span class=\"kw-bio\">HLA-B*5701</span> — <span class=\"kw-ci\">hypersensibilité</span>), <span class=\"kw-ttt\">azathioprine</span> et <span class=\"kw-ttt\">6-mercaptopurine</span> (gène TPMT — toxicité), 5-FU (déficit en DPD).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":6},{"id":"322-14","rang":"A","rubrique":"Prise en charge","titre":"Interactions médicamenteuses : connaître les principales classes médicamenteuses concernées","contenu":"<p><span class=\"kw-clinique\">Les</span> principales <span class=\"kw-def\">isoenzymes du CYP450</span> impliquées et leurs médicaments — substrats, inhibiteurs, inducteurs :</p>\n      <table >\n        <thead><tr><th>CYP</th><th>Substrats</th><th>Inhibiteurs</th><th>Inducteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1A2</strong></td><td><span class=\"kw-ttt\">Clozapine</span>, théophylline, caféine</td><td><span class=\"kw-ttt\">Ciprofloxacine</span>, fluvoxamine, énoxacine</td><td><span class=\"kw-alerte\">Fumée de tabac</span></td></tr>\n          <tr><td><strong>2C9</strong></td><td><span class=\"kw-ttt\">Warfarine</span>, acénocoumarol, <span class=\"kw-ttt\">phénytoïne</span></td><td>Amiodarone, <span class=\"kw-ttt\">fluconazole</span>, miconazole</td><td>Communs au 3A4</td></tr>\n          <tr><td><strong>2D6</strong><br>(non inductible)</td><td><span class=\"kw-ttt\">Codéine</span>, <span class=\"kw-ttt\">métoprolol</span>, <span class=\"kw-ttt\">flécaïnide</span>, tamoxifène</td><td>Fluoxétine, <span class=\"kw-ttt\">paroxétine</span>, quinidine</td><td>—</td></tr>\n          <tr><td><strong>3A4</strong><br>(le plus impliqué)</td><td>Voir liste détaillée ci-dessous</td><td>Mnémo <strong>JAMAiCa</strong></td><td>Mnémo <strong>PRECaMPaGNe</strong></td></tr>\n        </tbody>\n      </table>\n      <h4>Principaux substrats du CYP3A4</h4>\n      <p>Souvent à <span class=\"kw-def\">marge thérapeutique étroite</span> — <span class=\"kw-clinique\">les</span> plus exposés au risque de surdosage si co-prescription d'un inhibiteur :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Immunosuppresseurs</span></strong></td><td><span class=\"kw-ttt\">Ciclosporine</span>, <span class=\"kw-ttt\">tacrolimus</span>, sirolimus</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Anticoagulants</span></strong></td><td><span class=\"kw-ttt\">AOD</span> anti-Xa (<span class=\"kw-ttt\">apixaban</span>, <span class=\"kw-ttt\">rivaroxaban</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Statines</span></strong></td><td><span class=\"kw-ttt\">Atorvastatine</span>, <span class=\"kw-ttt\">simvastatine</span></td></tr>\n          <tr><td><strong>Contraception</strong></td><td>Œstroprogestatifs et progestatifs</td></tr>\n          <tr><td><strong>Dérivés de l'ergot de seigle</strong></td><td>Ergotamine, dihydroergotamine</td></tr>\n          <tr><td><strong>Benzodiazépines</strong></td><td>Midazolam, triazolam, zolpidem</td></tr>\n          <tr><td><strong>Morphiniques</strong></td><td>Fentanyl, méthadone, <span class=\"kw-ttt\">oxycodone</span>, alfentanil</td></tr>\n          <tr><td><strong>Anticancéreux</strong></td><td>Inhibiteurs de tyrosine kinase, docétaxel, vinca-alcaloïdes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Mnémo — inhibiteurs du CYP3A4 : JAMAiCa</strong> (risque de surdosage du substrat) :\n        <ul>\n          <li><strong>J</strong> — jus de pamplemousse</li>\n          <li><strong>A</strong> — <span class=\"kw-ttt\">amiodarone</span></li>\n          <li><strong>M</strong> — macrolides (sauf spiramycine)</li>\n          <li><strong>Ai</strong> — antifongiques azolés (kétoconazole, itraconazole, miconazole, <span class=\"kw-ttt\">voriconazole</span>, posaconazole)</li>\n          <li><strong>Ca</strong> — <span class=\"kw-ttt\">inhibiteurs calciques</span> bradycardisants (<span class=\"kw-ttt\">vérapamil</span>, diltiazem)</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Mnémo — inducteurs enzymatiques : PRECaMPaGNe</strong> (risque d'inefficacité du substrat) :\n        <ul>\n          <li><strong>P</strong> — <span class=\"kw-ttt\">phénobarbital</span></li>\n          <li><strong>R</strong> — <span class=\"kw-ttt\">rifampicine</span> +++, rifabutine</li>\n          <li><strong>E</strong> — éfavirenz</li>\n          <li><strong>Ca</strong> — carbamazépine, oxcarbazépine</li>\n          <li><strong>M</strong> — millepertuis +++, modafinil</li>\n          <li><strong>Pa</strong> — <span class=\"kw-ttt\">phénytoïne</span></li>\n          <li><strong>G</strong> — griséofulvine</li>\n          <li><strong>Ne</strong> — névirapine</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Pièges classiques.</strong><br>\n        <span class=\"kw-ttt\">Rifampicine</span> + contraception hormonale → <span class=\"kw-alerte\">échec contraceptif</span> ; + <span class=\"kw-ttt\">corticoïdes</span> → dose à augmenter de <span class=\"kw-chiffre\">30-50 %</span> ; + inhibiteurs de protéase du <span class=\"kw-etio\">VIH</span> → <span class=\"kw-ci\">contre-indication</span>.<br>\n        <span class=\"kw-ttt\">Codéine</span> : c'est un <strong>inhibiteur</strong> du CYP2D6 qui provoque la perte d'efficacité <span class=\"kw-ttt\">antalgique</span> (la <span class=\"kw-ttt\">codéine</span> est une prodrogue activée en <span class=\"kw-ttt\">morphine</span> par le CYP2D6).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":2}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"278c1217da77","n":322,"o":"322-1","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l’obèse","q":"Quelle est l'influence de l'obésité sur la clairance rénale des médicaments ?","a":"<p>L'obésité peut entraîner une <strong>augmentation de la clairance rénale</strong> (hyperfiltration glomérulaire) chez certains patients, en particulier ceux présentant une maladie rénale chronique associée. Cela peut nécessiter une <strong>adaptation de la posologie à la hausse</strong> pour les médicaments à élimination rénale.</p>"},{"i":"65d6e44d6a59","n":322,"o":"322-1","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l’obèse","q":"Comment l'obésité peut-elle impacter le volume de distribution des médicaments chez un patient ?","a":"<p>L'obésité peut <strong>augmenter le volume de distribution</strong> des médicaments <strong>lipophiles</strong> en raison de l'augmentation du tissu adipeux. Inversement, elle peut <strong>diminuer le volume de distribution</strong> des médicaments <strong>hydrophiles</strong>.</p>"},{"i":"7e1f26a4468b","n":322,"o":"322-1","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l’obèse","q":"Dans quel sens l'obésité peut-elle modifier le métabolisme hépatique des médicaments ?","a":"<p>L'obésité est souvent associée à une <strong>stéatose hépatique</strong> et à des modifications de l'activité enzymatique des cytochromes P450, pouvant potentiellement entraîner une <strong>diminution du métabolisme hépatique</strong> de certains médicaments, allongeant leur demi-vie et augmentant leur exposition.</p>"},{"i":"76fb30182865","n":322,"o":"322-10","u":"Prise en charge","t":"Connaître les principes du jeûne pré-anesthésie","q":"Pourquoi doit-on s'abstenir de sucer un bonbon ou de mâcher un chewing-gum juste avant une intervention chirurgicale nécessitant un jeûne ?","a":"<p>La mastication ou la succion stimule la <strong>sécrétion gastrique</strong>, augmentant ainsi le volume et l'acidité du contenu gastrique, ce qui contrevient à l'objectif du jeûne et accroît le risque d'inhalation en cas de régurgitation.</p>"},{"i":"93d885c66fb1","n":322,"o":"322-10","u":"Prise en charge","t":"Connaître les principes du jeûne pré-anesthésie","q":"Quelles sont les durées de jeûne recommandées concernant la prise des traitements per os habituels et le tabac avant un acte chirurgical programmé sous anesthésie chez l'adulte ?","a":"<ul><li>Pour les <strong>traitements per os habituels</strong> : <strong>2 heures</strong> (avec un verre d'eau le matin de l'intervention, sauf médicaments à risque comme les antithrombotiques).</li><li>Pour le <strong>tabac</strong> : <strong>≥ 2 heures</strong>.</li></ul>"},{"i":"9ef98e3a5e75","n":322,"o":"322-10","u":"Prise en charge","t":"Connaître les principes du jeûne pré-anesthésie","q":"Quelles sont les durées de jeûne recommandées avant un acte chirurgical programmé sous anesthésie pour les apports solides et liquides clairs chez l'adulte ?","a":"<ul><li>Pour les <strong>solides</strong> (repas léger) : <strong>6 heures</strong>.</li><li>Pour les <strong>liquides clairs</strong> (eau, thé, café, jus sans pulpe) : <strong>2 heures</strong>.</li></ul>"},{"i":"aeed60d48610","n":322,"o":"322-10","u":"Prise en charge","t":"Connaître les principes du jeûne pré-anesthésie","q":"Quel est l'objectif principal du jeûne pré-opératoire avant un acte sous anesthésie ?","a":"<p>L'objectif principal est d='éviter l'<strong>inhalation bronchique</strong> du contenu gastrique lors du contrôle des voies aériennes supérieures et de la ventilation artificielle.</p>"},{"i":"bd42c6638e85","n":322,"o":"322-10","u":"Prise en charge","t":"Connaître les principes du jeûne pré-anesthésie","q":"Dans quels cas l'inhalation bronchique reste-t-elle possible malgré un jeûne pré-opératoire parfaitement respecté ?","a":"<p>L'inhalation bronchique reste possible en cas de <strong>RGO sévère</strong> ou de <strong>pathologie gastro-œsophagienne</strong> sous-jacente.</p>"},{"i":"0ad410f052d6","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Quels sont les traitements qui sont habituellement maintenus en péri-opératoire et pourquoi ?","a":"<p>Les traitements suivants sont généralement maintenus en péri-opératoire :</p><ul><li><strong>Bêta-bloquants</strong>, <strong>inhibiteurs calciques</strong>, <strong>statines</strong>, <strong>SRAA de l'insuffisance cardiaque</strong> (pour éviter un risque de décompensation).</li><li><strong>Antiparkinsoniens</strong>, <strong>psychotropes</strong>, <strong>antiépileptiques</strong> (pour éviter un risque de syndrome de sevrage).</li></ul>"},{"i":"4e0e9e159ef2","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Quelle est la conduite à tenir pour les antiagrégants plaquettaires en péri-opératoire en cas de monothérapie ?","a":"<p>En <strong>monothérapie</strong> :</p><ul><li>La majorité des gestes sont réalisables sous <strong>aspirine à dose antiagrégante</strong>.</li><li>Si <strong>clopidogrel</strong> en monothérapie chez un coronarien → faire un <strong>relais par l'aspirine</strong>.</li><li>Certains gestes imposent l'arrêt de l'aspirine : chirurgie <strong>ORL, urologique, neurologique</strong>.</li><li>Délai d'arrêt de l'aspirine si nécessaire : <strong>3 jours</strong> (<strong>5 jours</strong> si neurochirurgie intracrânienne / ORL).</li></ul>"},{"i":"53d87dd23322","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Quels sont les traitements à risque en cas de poursuite péri-opératoire et leurs risques associés ?","a":"<ul><li><strong>Antiagrégants plaquettaires, anticoagulants</strong> : risque hémorragique.</li><li><strong>Antagonistes du SRA</strong> : majoration du risque d'<strong>hypotension artérielle</strong> sous anesthésie générale.</li><li><strong>Biguanides (metformine)</strong> : risque d'<strong>acidose lactique</strong>.</li><li><strong>Sulfamides, glinides</strong> : risque d'<strong>hypoglycémie</strong> pendant le jeûne pré-interventionnel.</li><li><strong>Corticothérapie au long cours</strong> : risque d'<strong>insuffisance surrénalienne aiguë</strong>.</li></ul>"},{"i":"624feea394d1","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Quelles sont les grandes stratégies de gestion des traitements péri-opératoires en fonction du risque hémorragique du geste et du risque thrombotique du patient ?","a":"<p>La gestion péri-opératoire des traitements est <strong>pluridisciplinaire</strong> (anesthésiste, chirurgien, cardiologue...). Elle vise à arbitrer en permanence entre le <strong>risque hémorragique du geste</strong> chirurgical et le <strong>risque thrombotique du patient</strong>. Les traitements peuvent être arrêtés, maintenus, ou faire l'objet d'un relais temporaire.</p>"},{"i":"6a64da155062","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Quels sont les traitements pour lesquels une attention particulière est requise en péri-opératoire et quelle est la conduite à tenir spécifique pour chacun ?","a":"<ul><li><strong>Diurétiques</strong> : non pris le matin de l'intervention.</li><li><strong>SRAA à visée anti-HTA</strong> : arrêt <strong>12-24 heures avant</strong> (risque d'hypotension avec les anesthésiants).</li><li><strong>Corticothérapie au long cours</strong> : ne jamais arrêter brutalement. Opothérapie substitutive par <strong>hydrocortisone</strong> : <strong>25 à 75 mg</strong> si chirurgie mineure/modérée ; <strong>50 mg / 6 heures</strong> jusqu'à H48-72 si chirurgie majeure.</li><li><strong>Biguanides (metformine)</strong> : chirurgie mineure sans produit de contraste → pas d'arrêt. Sinon : arrêt <strong>12-24 heures avant</strong>, reprise <strong>48 heures après</strong> (si fonction rénale OK et reprise alimentation).</li><li><strong>Sulfamides, glinides</strong> : arrêt la veille ou le matin si chirurgie majeure (risque d'hypoglycémie pendant le jeûne).</li></ul>"},{"i":"6d022baf1596","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Comment sont gérés les Anticoagulants Oraux Directs (AOD) en période péri-opératoire ?","a":"<p>La gestion des AOD est calquée sur celle des AVK, mais <strong>sans relais héparine</strong> chez le patient à haut risque thrombo-embolique (en raison d'un surrisque hémorragique).</p><ul><li><strong>Faible risque hémorragique</strong> : pas de prise la veille au soir ni le matin de l'intervention ; reprise <strong>≥ 6 heures après</strong>.</li><li><strong>Risque hémorragique élevé</strong> : dernière prise à <strong>J-3</strong> (xabans) ou <strong>J-4</strong> (dabigatran) ; <strong>J-5</strong> si très haut risque hémorragique, ou si insuffisance rénale modérée pour le dabigatran.</li><li>En post-opératoire : <strong>anticoagulation prophylactique ≥ 6 heures après</strong>, curative dès que l'hémostase le permet.</li></ul>"},{"i":"a6463055d115","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Quelle est la prise en charge péri-opératoire des AVK en fonction du risque thrombo-embolique ?","a":"<ul><li><strong>Faible risque thrombo-embolique</strong> (FA sans ATCD embolique, MTEV à risque modéré) : arrêt de l'AVK <strong>3 à 4 jours</strong> avant, <strong>sans relais</strong>, pour normaliser l'INR. Reprise le soir même ou dans les 24-48h.</li><li><strong>Élevé risque thrombo-embolique</strong> (valve mécanique, FA avec ATCD embolique, MTEV à haut risque) : arrêt de l'AVK <strong>4 à 5 jours</strong> avant + <strong>relais pré-opératoire par héparine à dose curative</strong>. Reprise de l'héparine <strong>6 heures après</strong> le geste (jamais avant), puis relais héparine → AVK.</li><li>L'objectif d'<strong>INR est &lt; 1,5</strong> le jour de l'acte si un arrêt est nécessaire.</li><li>Piège : les <strong>AINS sont contre-indiqués en post-opératoire</strong> chez un patient sous AVK.</li></ul>"},{"i":"e85157228cd0","n":322,"o":"322-11","u":"Prise en charge","t":"Connaître les principes de gestion pluridisciplinaire des traitements avant une intervention ou une anesthésie","q":"Comment gérer une bithérapie antiagrégante plaquettaire (AAS + inhibiteur P2Y12) en péri-opératoire ?","a":"<p>En <strong>bithérapie</strong> (AAS + clopidogrel / ticagrelor / prasugrel) :</p><ul><li>La majorité des gestes ne sont <strong>pas réalisables</strong>.</li><li>Après <strong>stent</strong>, il faut <strong>retarder tout acte non urgent</strong> : <strong>≥ 6 semaines</strong> si stent nu, <strong>3 à 6 mois</strong> si stent actif (risque majeur de thrombose de stent).</li><li>Si l'acte ne peut être différé : l'<strong>aspirine est toujours maintenue</strong>, et l'arrêt de l'inhibiteur du P2Y12 est le plus court possible.</li><li>Pour les endoscopies : <strong>endoscopie digestive ± biopsie possible</strong> sous bi-antiagrégation ; endoscopie bronchique avec biopsies possible sous aspirine seule.</li><li>Délais d'arrêt des inhibiteurs du P2Y12 si nécessaire : <strong>clopidogrel et ticagrelor 5 jours</strong> ; <strong>prasugrel 7 jours</strong>.</li></ul>"},{"i":"58a715d51111","n":322,"o":"322-13","u":"Prise en charge","t":"Interactions médicamenteuses : identifier les principaux mécanismes d'interactions médicamenteuses","q":"Quelle est la différence entre une induction et une inhibition enzymatique au niveau du cytochrome P450 ?","a":"<ul><li><strong>Induction enzymatique</strong> : le métabolisme du substrat est <strong>accéléré</strong>, ce qui <strong>diminue</strong> sa concentration et expose à un risque d'<strong>inefficacité</strong> (sous-dosage). Le délai est <strong>retardé</strong> (10-15 jours) et réversible progressivement. L'induction est peu spécifique.</li><li><strong>Inhibition enzymatique</strong> : le métabolisme du substrat est <strong>ralenti</strong>, ce qui <strong>augmente</strong> sa concentration et expose à un risque de <strong>toxicité</strong> (surdosage). Le délai est <strong>rapide</strong>. L'inhibition est spécifique d'un CYP donné.</li></ul>"},{"i":"c8229f8629ff","n":322,"o":"322-13","u":"Prise en charge","t":"Interactions médicamenteuses : identifier les principaux mécanismes d'interactions médicamenteuses","q":"Quels sont les deux grands mécanismes d'interactions médicamenteuses ?","a":"<p>Les deux grands mécanismes sont :</p><ul><li>Les interactions <strong>pharmacodynamiques</strong> : les médicaments agissent sur la même cible ou fonction, leurs concentrations plasmatiques sont inchangées. Elles sont généralement prévisibles et peuvent être une synergie, un antagonisme (ex: agoniste dopaminergique + neuroleptique) ou des effets indésirables additifs (ex: torsades de pointe, médicaments sérotoninergiques).</li><li>Les interactions <strong>pharmacocinétiques</strong> : un médicament modifie une étape pharmacocinétique (PK) d'un autre (absorption, liaison protéique, métabolisme, élimination rénale), augmentant (toxicité) ou diminuant (inefficacité) sa concentration.</li></ul>"},{"i":"f84469bbb838","n":322,"o":"322-13","u":"Prise en charge","t":"Interactions médicamenteuses : identifier les principaux mécanismes d'interactions médicamenteuses","q":"Quand la pharmacogénétique est-elle utile dans la prévention des interactions médicamenteuses ?","a":"<p>La pharmacogénétique permet d'identifier les patients à risque (métaboliseurs lents ou ultra-rapides) en raison de leur génotype qui module la pharmacocinétique/pharmacodynamie des médicaments. Un <strong>génotypage</strong> est recommandé au RCP (Résumé des Caractéristiques du Produit) avant certains traitements pour prévenir des réactions graves :</p><ul><li><strong>Abacavir</strong> et <strong>carbamazépine</strong> : génotype <strong>HLA-B*5701</strong> pour hypersensibilité.</li><li><strong>Azathioprine</strong> et <strong>6-mercaptopurine</strong> : gène <strong>TPMT</strong> pour toxicité.</li><li><strong>5-FU</strong> : déficit en <strong>DPD</strong> (dihydropyrimidine déshydrogénase).</li></ul>"},{"i":"fd2a8990e699","n":322,"o":"322-13","u":"Prise en charge","t":"Interactions médicamenteuses : identifier les principaux mécanismes d'interactions médicamenteuses","q":"Comment l'ANSM classe-t-elle le risque clinique des interactions médicamenteuses ?","a":"<p>L'ANSM attribue un <strong>niveau de contrainte</strong> aux interactions à risque clinique :</p><ul><li><strong>Contre-indication</strong> : l'association ne doit pas être prescrite.</li><li><strong>Association déconseillée</strong> : à éviter sauf absence d'alternative, nécessite une surveillance étroite.</li><li><strong>Précaution d'emploi</strong> : association possible avec surveillance renforcée (clinique, biologique, ECG, concentrations plasmatiques) et adaptation des posologies.</li><li><strong>À prendre en compte</strong> : simple majoration d'un risque additif d'effets indésirables (ex: sédatifs, atropiniques).</li></ul>"},{"i":"4434594f6b48","n":322,"o":"322-14","u":"Prise en charge","t":"Interactions médicamenteuses : connaître les principales classes médicamenteuses concernées","q":"Quels sont les principaux substrats, souvent à marge thérapeutique étroite, du CYP3A4, et donc les plus exposés au risque de surdosage si co-prescription d'un inhibiteur ?","a":"<p>Les principaux substrats du CYP3A4 avec une marge thérapeutique étroite sont :</p><ul><li>Immunosuppresseurs : <strong>ciclosporine</strong>, <strong>tacrolimus</strong>, sirolimus.</li><li>Anticoagulants : <strong>AOD anti-Xa</strong> (apixaban, rivaroxaban).</li><li>Statines : <strong>atorvastatine</strong>, <strong>simvastatine</strong>.</li><li>Contraception : <strong>œstroprogestatifs</strong> et <strong>progestatifs</strong>.</li><li>Dérivés de l'ergot de seigle : ergotamine, dihydroergotamine.</li><li>Benzodiazépines : midazolam, triazolam, zolpidem.</li><li>Morphiniques : fentanyl, méthadone, oxycodone, alfentanil.</li><li>Anticancéreux : inhibiteurs de tyrosine kinase, docétaxel, vinca-alcaloïdes.</li></ul>"},{"i":"6b6524f08b68","n":322,"o":"322-14","u":"Prise en charge","t":"Interactions médicamenteuses : connaître les principales classes médicamenteuses concernées","q":"Quelles sont les principales isoenzymes du CYP450 impliquées dans les interactions médicamenteuses, et citer pour chacune un exemple de substrat et un de leurs inducteurs/inhibiteurs ?","a":"<p>Les principales isoenzymes du CYP450 impliquées sont :</p><ul><li><strong>CYP1A2</strong> : Substrat (Clozaril, caféine), Inhibiteur (ciprofloxacine), Inducteur (fumée de tabac).</li><li><strong>CYP2C9</strong> : Substrat (warfarine, phénytoïne), Inhibiteur (amiodarone, fluconazole), Inducteur (communs au 3A4).</li><li><strong>CYP2D6</strong> (non inductible) : Substrat (codéine, métoprolol, tamoxifène), Inhibiteur (fluoxétine, paroxétine).</li><li><strong>CYP3A4</strong> (le plus impliqué) : Voir exemples spécifiques de substrats, inhibiteurs et inducteurs ci-dessous.</li></ul>"},{"i":"b02b032fdaf7","n":322,"o":"322-14","u":"Prise en charge","t":"Interactions médicamenteuses : connaître les principales classes médicamenteuses concernées","q":"Quels sont les pièges classiques d'interactions médicamenteuses concernant la rifampicine et la codéine ?","a":"<ul><li>La <strong>rifampicine</strong> :<ul><li>Avec la <strong>contraception hormonale</strong> : risque d'échec contraceptif.</li><li>Avec les <strong>corticoïdes</strong> : nécessite d'augmenter la dose des corticoïdes de 30-50 %.</li><li>Avec les <strong>inhibiteurs de protéase du VIH</strong> : c'est une contre-indication.</li></ul></li><li>La <strong>codéine</strong> : c'est une prodrogue activée en morphine par le CYP2D6. Tout inhibiteur du <strong>CYP2D6</strong> (comme la fluoxétine ou la paroxétine) peut entraîner une perte de son efficacité antalgique.</li></ul>"},{"i":"b13d0bbde794","n":322,"o":"322-14","u":"Prise en charge","t":"Interactions médicamenteuses : connaître les principales classes médicamenteuses concernées","q":"Citer les principaux inhibiteurs enzymatiques du CYP3A4 (mnémotechnique JAMAiCa) et les principaux inducteurs enzymatiques (mnémotechnique PRECaMPaGNe).","a":"<ul><li><strong>Inhibiteurs du CYP3A4</strong> (mnémotechnique <strong>JAMAiCa</strong> - risque de surdosage du substrat) :<ul><li><strong>J</strong> : Jus de pamplemousse</li><li><strong>A</strong> : Amiodarone</li><li><strong>M</strong> : Macrolides (sauf spiramycine)</li><li><strong>Ai</strong> : Antifongiques azolés (kétoconazole, itraconazole, miconazole, voriconazole, posaconazole)</li><li><strong>Ca</strong> : Inhibiteurs calciques bradycardisants (vérapamil, diltiazem)</li></ul></li><li><strong>Inducteurs enzymatiques</strong> (mnémotechnique <strong>PRECaMPaGNe</strong> - risque d'inefficacité du substrat) :<ul><li><strong>P</strong> : Phénobarbital</li><li><strong>R</strong> : Rifampicine +++, rifabutine</li><li><strong>E</strong> : Éfavirenz</li><li><strong>Ca</strong> : Carbamazépine, oxcarbazépine</li><li><strong>M</strong> : Millepertuis +++, modafinil</li><li><strong>Pa</strong> : Phénytoïne</li><li><strong>G</strong> : Griséofulvine</li><li><strong>Ne</strong> : Névirapine</li></ul></li></ul>"},{"i":"5297deee7cff","n":322,"o":"322-2","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'enfant","q":"Pourquoi l'aspect psychosocial est-il crucial dans la décision thérapeutique personnalisée chez l'enfant ?","a":"<p>L'aspect psychosocial est crucial pour plusieurs raisons :</p><ul><li>La <strong>participation des parents/tuteurs</strong> est indispensable pour l'explication de la maladie, du traitement et l'obtention du consentement éclairé.</li><li>La <strong>perception de la maladie</strong> et du traitement par l'enfant varie avec son âge et son niveau de développement, nécessitant une communication adaptée.</li><li>L'<strong>impact sur la qualité de vie</strong> de l'enfant et de sa famille doit être considéré, notamment pour les traitements chroniques.</li><li>Les <strong>contexte familial et socio-économique</strong> peuvent influencer l'observance thérapeutique et l'accès aux soins.</li><li>La <strong>gestion de la douleur</strong> et de l'anxiété liées aux soins est primordiale pour ne pas traumatiser l'enfant.</li></ul><p>Une approche <strong>centrée sur l'enfant et sa famille</strong> est donc essentielle pour optimiser l'adhésion au traitement et le bien-être général.</p>"},{"i":"accbd770fd84","n":322,"o":"322-2","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'enfant","q":"Quels sont les principes fondamentaux de l'adaptation thérapeutique en pédiatrie ?","a":"<p>L'adaptation thérapeutique chez l'enfant repose sur plusieurs principes clés :</p><ul><li>La <strong>croissance</strong> et le <strong>développement</strong> de l'enfant impactent la pharmacocinétique et la pharmacodynamie.</li><li>Les <strong>variations inter-individuelles</strong> sont plus marquées que chez l'adulte.</li><li>La <strong>balance bénéfice/risque</strong> est particulièrement critique.</li><li>Nécessité d'une <strong>posologie adaptée</strong> au poids, à l'âge et à la surface corporelle.</li><li>Prise en compte de la <strong>tolérance</strong> et des <strong>effets indésirables spécifiques</strong> à l'enfant.</li><li>Importance de l'<strong>observance thérapeutique</strong>, souvent dépendante des parents ou du tuteur légal.</li><li>Privilégier les <strong>formes galéniques adaptées</strong> (liquides, orodispersibles).</li></ul>"},{"i":"adf4b1d280a5","n":322,"o":"322-2","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'enfant","q":"Comment la pharmacocinétique est-elle modifiée chez l'enfant par rapport à l'adulte, et quelles en sont les implications pour l'adaptation thérapeutique ?","a":"<p>Chez l'enfant, la pharmacocinétique est modifiée à plusieurs niveaux :</p><ul><li><strong>Absorption</strong> : La vidange gastrique, le pH gastrique et la surface d'absorption intestinale varient avec l'âge.</li><li><strong>Distribution</strong> : Le volume de distribution est souvent plus important en raison d'une proportion d'eau corporelle totale plus élevée et d'une quantité de graisses relative plus faible. La liaison aux protéines plasmatiques peut être réduite.</li><li><strong>Métabolisme</strong> : L'activité des enzymes hépatiques (cytochromes P450) est immature à la naissance et se développe progressivement, conduisant à des capacités de métabolisation variables.</li><li><strong>Élimination</strong> : La fonction rénale (filtration glomérulaire et fonction tubulaire) est immature chez le nouveau-né et le jeune nourrisson, augmentant le risque d'accumulation des médicaments.</li></ul><p>Ces modifications impliquent une <strong>adaptation rigoureuse des doses</strong>, des <strong>intervalles entre les prises</strong> et une <strong>surveillance accrue de la toxicité</strong> ou de l'inefficacité thérapeutique.</p>"},{"i":"1cb83e9650e9","n":322,"o":"322-3","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique pendant la grossesse et l'allaitement","q":"Quelle est la principale ressource à consulter pour l'adaptation thérapeutique des médicaments pendant la grossesse et l'allaitement en France ?","a":"<p>La principale ressource à consulter est le <strong>CRAT</strong> (Centre de Référence sur les Agents Tératogènes), qui fournit des informations détaillées et actualisées sur la compatibilité des médicaments avec la grossesse et l'allaitement.</p>"},{"i":"483409ebba50","n":322,"o":"322-3","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique pendant la grossesse et l'allaitement","q":"Quels sont les principes généraux à respecter pour la prescription médicamenteuse pendant la grossesse ?","a":"<p>Les principes généraux incluent :<ul><li><strong>Évaluer la nécessité réelle du traitement</strong>.</li><li>Choisir le médicament le <strong>moins tératogène</strong> ou embryotoxique connu.</li><li>Utiliser la <strong>dose efficace minimale</strong>.</li><li>Prescrire pendant la <strong>période la moins à risque</strong> (éviter le 1er trimestre si possible pour les molécules à risque).</li><li>Informer la patiente des <strong>risques potentiels et des bénéfices attendus</strong>.</li></ul></p>"},{"i":"5c138f61e77e","n":322,"o":"322-3","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique pendant la grossesse et l'allaitement","q":"Quelles sont les considérations majeures pour la prescription médicamenteuse pendant l'allaitement ?","a":"<p>Les considérations majeures sont :<ul><li>Le <strong>passage du médicament dans le lait maternel</strong>.</li><li>La <strong>quantité de lait ingérée</strong> par le nourrisson.</li><li>Les <strong>effets potentiels du médicament sur le nourrisson</strong> (toxicité, effets indésirables).</li><li>L'<strong>âge du nourrisson</strong> (les nouveau-nés sont plus sensibles).</li><li>La <strong>demie-vie du médicament</strong> et le <strong>moment d'administration</strong> par rapport aux tétées.</li></ul></p>"},{"i":"68faf9677e54","n":322,"o":"322-3","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique pendant la grossesse et l'allaitement","q":"Quel est l'objectif principal de l'adaptation thérapeutique pendant la grossesse et l'allaitement ?","a":"<p>L'objectif principal est de <strong>concilier l'efficacité du traitement maternel</strong> avec la <strong>sécurité du fœtus ou du nourrisson</strong>, en minimisant les risques de tératogénicité ou d'effets indésirables chez l'enfant.</p>"},{"i":"4b46172d3869","n":322,"o":"322-4","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez la personne âgée (voir item 130)","q":"Quels sont les outils reconnus pour optimiser la prescription médicamenteuse et l'adaptation thérapeutique chez la personne âgée ?","a":"<p>Les outils reconnus sont :</p><ul><li>Les <strong>critères STOPP</strong> (Screening Tool of Older Person's Potentially Inappropriate Prescriptions).</li><li>Les <strong>critères START</strong> (Screening Tool to Alert doctors to Right Treatment).</li></ul>"},{"i":"bbd1d81e65e0","n":322,"o":"322-4","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez la personne âgée (voir item 130)","q":"Quel est le principal facteur physiologique à prendre en compte pour l'adaptation thérapeutique médicamenteuse chez la personne âgée ?","a":"<p>Le principal facteur physiologique est la <strong>baisse physiologique du débit de filtration glomérulaire (DFG)</strong>, qui affecte l'élimination rénale des médicaments.</p>"},{"i":"edebb93ec702","n":322,"o":"322-4","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez la personne âgée (voir item 130)","q":"Quels concepts majeurs, liés à la polymédication, sont à considérer dans l'adaptation thérapeutique chez la personne âgée ?","a":"<p>Les concepts majeurs sont :</p><ul><li>La <strong>polymédication</strong> elle-même.</li><li>La <strong>cascade iatrogène</strong>, où un nouveau médicament est prescrit pour traiter un effet indésirable d'un autre médicament.</li><li>La <strong>déprescription</strong>, ou réduction et arrêt des médicaments inutiles ou potentiellement dangereux.</li></ul>"},{"i":"038d80d7006b","n":322,"o":"322-5","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'insuffisant rénal","q":"Quelles mesures de prévention de la néphrotoxicité médicamenteuse doivent être mises en place ?","a":"<p>La prévention de la néphrotoxicité médicamenteuse implique :</p><ul><li>Une <strong>mesure préalable de la fonction rénale</strong>.</li><li>La <strong>correction d'une hypovolémie</strong> et des troubles électrolytiques.</li><li>L'<strong>adaptation des doses</strong> des médicaments.</li><li>Une <strong>surveillance</strong> régulière de la fonction rénale, du sédiment urinaire et des taux plasmatiques.</li><li>Une <strong>réévaluation régulière de la pertinence</strong> de la prescription.</li></ul>"},{"i":"10b2db2c18a9","n":322,"o":"322-5","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'insuffisant rénal","q":"Quelles classes de médicaments sont reconnues pour leur néphrotoxicité, et quels sont les types d'atteinte rénale associés ?","a":"<p>Plusieurs classes de médicaments sont néphrotoxiques :</p><ul><li><strong>Antibiotiques</strong> : <strong>Aminosides</strong> (NTA), <strong>ciprofloxacine</strong> (NIA, précipitation), <strong>β-lactamines</strong> (NIA immuno-allergique).</li><li><strong>Antiviraux</strong> : <strong>Ténofovir</strong>, <strong>cidofovir</strong>, <strong>adéfovir</strong>, <strong>aciclovir</strong>, <strong>indinavir</strong> (NTA).</li><li><strong>Antifongique</strong> : <strong>Amphotéricine B</strong> (NTA).</li><li><strong>Chimiothérapie</strong> : <strong>Sels de platine</strong>, <strong>méthotrexate</strong> (NTA) ; <strong>ifosfamide</strong> (tubulopathie, IRA) ; <strong>mitomycine C</strong>, <strong>gemcitabine</strong> (MAT).</li><li><strong>Thérapies ciblées / immunothérapies</strong> : Anti-angiogéniques et inhibiteurs de tyrosine kinase (MAT) ; interférons (MAT) ; inhibiteurs de checkpoint <strong>anti-CTLA-4 / anti-PD-1</strong> (néphrite tubulo-interstitielle).</li><li><strong>Analgésiques</strong> : <strong>AINS</strong> (perturbation hémodynamique rénale, NIA immuno-allergique, glomérulopathie).</li><li><strong>Immunosuppresseurs</strong> : <strong>Ciclosporine</strong>, <strong>tacrolimus</strong> (toxicité vasculaire, NTA) ; inhibiteurs de mTOR (NTA).</li><li><strong>Autres</strong> : <strong>Produits de contraste iodés</strong> (NTA) ; <strong>lithium</strong> (NTA, IR chronique) ; <strong>IPP</strong> (NIA, IR chronique) ; <strong>biphosphonates</strong> ; <strong>IEC/ARA2</strong> et <strong>diurétiques</strong> (toxicité indirecte : hémodynamique rénale, déshydratation).</li></ul>"},{"i":"1f135f2adcfc","n":322,"o":"322-5","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'insuffisant rénal","q":"Comment l'insuffisance rénale affecte-t-elle la pharmacocinétique des médicaments au niveau de la biodisponibilité et de la distribution ?","a":"<p>L'insuffisance rénale modifie la pharmacocinétique :</p><ul><li><strong>Biodisponibilité</strong> : la modification du pH gastrique et le ralentissement du transit peuvent entraîner une <strong>absorption diminuée ou retardée</strong> des médicaments.</li><li><strong>Distribution</strong> : les œdèmes augmentent le volume de distribution, tandis que la déshydratation ou la fonte musculaire peuvent le diminuer, augmentant ainsi la concentration. L'hypoalbuminémie et les toxines urémiques <strong>augmentent la fraction libre active</strong> des médicaments liés aux protéines.</li></ul>"},{"i":"5cbbd685ca1a","n":322,"o":"322-5","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'insuffisant rénal","q":"Comment doit-on évaluer et adapter la posologie des médicaments chez un patient insuffisant rénal ?","a":"<p>L'évaluation et l'adaptation de la posologie se font comme suit :</p><ul><li><strong>Évaluation</strong> : elle repose sur des données cliniques (poids, volume extra-cellulaire) et l'estimation du DFG, principalement avec la formule <strong>CKD-EPI</strong> (référence) ou <strong>Cockcroft-Gault</strong> (utilisée pour les RCP).</li><li><strong>Adaptation de la dose</strong> : on peut <strong>diminuer les doses</strong> (si index thérapeutique étroit et demi-vie courte) ou <strong>espacer les prises</strong> (si demi-vie longue et index large), voire faire les deux.</li><li>En cas d'<strong>IRA</strong>, la fonction rénale est difficile à évaluer (créatinine marqueur retardé), il faut donc privilégier le <strong>monitorage des concentrations plasmatiques</strong> des médicaments si disponible.</li></ul>"},{"i":"631bc11c8abf","n":322,"o":"322-5","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez l'insuffisant rénal","q":"Quels sont les mécanismes par lesquels l'insuffisance rénale impacte l'élimination des médicaments ?","a":"<p>L'insuffisance rénale altère l'élimination des médicaments de plusieurs manières :</p><ul><li><strong>Élimination hépatique</strong> : les toxines urémiques peuvent altérer les activités enzymatiques hépatiques (cytochromes, glucuronidation, acétylation).</li><li><strong>Élimination rénale</strong> : elle combine un défaut de filtration glomérulaire et une altération des transporteurs tubulaires, souvent par compétition avec les toxines urémiques. Il est important de noter que l'altération des fonctions tubulaires n'est pas proportionnelle au DFG, rendant hasardeuse la prédiction du comportement d'un médicament basée uniquement sur le DFG estimé.</li></ul>"},{"i":"0995a4beeb17","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quels sont les médicaments à fort premier passage hépatique dont la posologie doit être réduite en cas de cirrhose ?","a":"<p>Les médicaments à fort premier passage hépatique dont la posologie doit être réduite en cas de cirrhose incluent :</p><ul><li><strong>Antagonistes calciques</strong> et <strong>β-bloquants</strong>.</li><li><strong>Statines</strong> et <strong>morphine</strong>.</li><li><strong>Sumatriptan</strong>.</li><li><strong>Antidépresseurs</strong>, <strong>antipsychotiques</strong>, <strong>anxiolytiques</strong>, <strong>hypnotiques</strong>.</li><li><strong>Antiparkinsoniens</strong>.</li></ul>"},{"i":"2c4883a6bacb","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quels médicaments sont contre-indiqués en cas de tumeurs bénignes du foie (adénome, adénomatose) ?","a":"<p>En cas de tumeurs bénignes du foie (adénome, adénomatose), les <strong>œstrogènes</strong>, les <strong>androgènes</strong> et les <strong>stéroïdes anabolisants</strong> sont contre-indiqués.</p>"},{"i":"3b626e3fb10a","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quels sont les mécanismes fondamentaux qui influent sur la biotransformation des médicaments dans le foie ?","a":"<p>La biotransformation hépatique des médicaments liposolubles en métabolites hydrosolubles se fait en deux phases :</p><ul><li><strong>Phase I</strong> : oxydation, principalement par le système du <strong>cytochrome P450</strong>, produisant des métabolites intermédiaires.</li><li><strong>Phase II</strong> : conjugaison ou acétylation, produisant des métabolites polaires et hydrosolubles pour l'élimination.</li></ul>"},{"i":"697effbed942","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quels sont les médicaments à hépatotoxicité élevée en cas d'hépatopathie fibrosante, même sans insuffisance hépatocellulaire ni hypertension portale ?","a":"<p>Les médicaments présentant une hépatotoxicité élevée en cas d'hépatopathie fibrosante incluent :</p><ul><li><strong>AINS</strong> et <strong>paracétamol</strong> (à doses suprathérapeutiques).</li><li><strong>Antituberculeux</strong> et <strong>azathioprine</strong>.</li><li><strong>Valproate</strong> et <strong>vitamine A</strong>.</li><li><strong>Antiviraux anti-VIH</strong>.</li></ul>"},{"i":"6a0ed7d608ad","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quelle est la conduite à tenir en matière de prescription médicamenteuse en cas d'insuffisance hépatocellulaire aiguë ictérique ?","a":"<p>En cas d'insuffisance hépatocellulaire aiguë ictérique :</p><ul><li>Arrêter toute <strong>médication non vitale</strong>.</li><li>Si une anticoagulation est nécessaire, remplacer les <strong>AVK</strong> par l'<strong>héparine</strong> pendant l'épisode aigu.</li></ul>"},{"i":"772b6d7c415b","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quel principe général doit-on appliquer si un médicament hépatotoxique est indispensable chez un patient avec hépatopathie ?","a":"<p>Si un médicament hépatotoxique est indispensable chez un patient avec hépatopathie, il faut préférer ceux responsables d'<strong>hépatites cholestatiques</strong> plutôt que <strong>cytolytiques</strong>.</p>"},{"i":"974018cc160e","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Comment l'insuffisance hépatique ou l'hypertension portale affecte-t-elle la pharmacocinétique des médicaments ?","a":"<p>L'insuffisance hépatique ou l'hypertension portale modifie plusieurs paramètres :</p><ul><li><strong>Effet de premier passage hépatique</strong> : sa diminution due à la baisse du débit sanguin hépatique et aux shunts porto-caves, augmente la concentration des médicaments à fort premier passage, nécessitant une réduction de posologie.</li><li><strong>Prodrogues</strong> : leur activation hépatique est altérée, entraînant une perte d'efficacité.</li><li><strong>Liaison protéique</strong> : la baisse de synthèse d'<strong>albumine</strong> augmente la fraction libre et l'effet des médicaments fortement liés.</li><li><strong>Déplétion en glutathion</strong> : l'altération de la défense antioxydante (dénutrition et IHC) majore l'hépatotoxicité.</li></ul>"},{"i":"b9a7380b95a5","n":322,"o":"322-6","u":"Prise en charge","t":"Connaître les principes d'adaptation thérapeutique chez le patient atteint d’insuffisance hépatique","q":"Quelles sont les contre-indications médicamenteuses spécifiques en cas de cirrhose avec insuffisance hépatocellulaire (Child B et C) ?","a":"<p>En cas de cirrhose avec insuffisance hépatocellulaire (Child B et C) :</p><ul><li>Les <strong>AINS</strong> sont formellement contre-indiqués quel que soit le degré d'IHC.</li><li>Les <strong>aminosides</strong> sont contre-indiqués en cas d'ictère.</li><li>La <strong>colchicine</strong> est contre-indiquée (hépatite aiguë, cirrhose Child B et C).</li><li>Le <strong>sérum glucosé</strong> est contre-indiqué avant injection de <strong>vitamine B1</strong> en cas de dénutrition, pour éviter la survenue d'une encéphalopathie de Wernicke.</li></ul>"},{"i":"30851ce1587c","n":322,"o":"322-7","u":"Prise en charge","t":"Connaître les principes d’une décision médicale partagée avec un malade et son entourage (voir item 3)","q":"Qu'implique le consentement éclairé du patient dans le processus de décision médicale partagée ?","a":"<p>Le consentement éclairé signifie que le patient, après avoir reçu une <strong>information complète et compréhensible</strong>, et après avoir eu l'occasion d'exprimer ses préférences et de poser des questions, <strong>accepte librement</strong> une intervention ou un traitement proposé. Il ne s'agit pas d'une simple acceptation, mais d'une adhésion réfléchie à la décision thérapeutique.</p>"},{"i":"5db630b55df1","n":322,"o":"322-7","u":"Prise en charge","t":"Connaître les principes d’une décision médicale partagée avec un malade et son entourage (voir item 3)","q":"Quel est le rôle du recueil des préférences du patient et de son entourage dans la décision médicale partagée ?","a":"<p>Il est essentiel de <strong>solliciter activement</strong> les valeurs, les attentes, les craintes et les priorités du patient (et de ses proches s'il le souhaite ou si sa capacité de décision est altérée). Cela permet au médecin de proposer des options thérapeutiques qui sont non seulement médicalement appropriées, mais aussi <strong>alignées avec le projet de vie</strong> et les objectifs du patient.</p>"},{"i":"62ef61c68b46","n":322,"o":"322-7","u":"Prise en charge","t":"Connaître les principes d’une décision médicale partagée avec un malade et son entourage (voir item 3)","q":"Comment la balance bénéfice/risque doit-elle être expliquée au patient dans la décision médicale partagée ?","a":"<p>La balance bénéfice/risque doit être présentée de manière <strong>claire et objective</strong>, en détaillant les <strong>avantages attendus</strong> de chaque option thérapeutique (ex: amélioration des symptômes, augmentation de l'espérance de vie) ainsi que les <strong>inconvénients potentiels</strong> (effets secondaires, complications, contraintes). Il est crucial d'aider le patient à comprendre les <strong>probabilités</strong> associées à ces bénéfices et risques, sans minimiser ni dramatiser.</p>"},{"i":"955bbc00ffed","n":322,"o":"322-7","u":"Prise en charge","t":"Connaître les principes d’une décision médicale partagée avec un malade et son entourage (voir item 3)","q":"Qu'est-ce que l'information loyale, claire et adaptée dans le cadre de la décision médicale partagée ?","a":"<p>C'est la communication par le médecin au patient et à son entourage de toutes les informations pertinentes concernant sa pathologie, les options thérapeutiques, leurs bénéfices, leurs risques et leurs alternatives. Cette information doit être <strong>honnête</strong>, <strong>compréhensible</strong> par le patient (adaptée à son niveau de compréhension) et <strong>suffisamment complète</strong> pour éclairer sa décision.</p>"},{"i":"51fbc478bb1d","n":322,"o":"322-8","u":"Prise en charge","t":"Connaître les principes de la prescription médicamenteuse, les modalités de surveillance et d’arrêt","q":"Comment doit être menée la surveillance d'un traitement médicamenteux ?","a":"<p>La surveillance d'un traitement médicamenteux doit évaluer :</p><ul><li>L'<strong>efficacité</strong> du traitement.</li><li>La <strong>tolérance</strong> et la survenue d'éventuels effets indésirables.</li><li>L'<strong>observance</strong> du patient.</li><li>La nécessité de réaliser des <strong>dosages plasmatiques</strong> si le médicament possède une marge thérapeutique étroite.</li></ul>"},{"i":"ce6bf8a4ab80","n":322,"o":"322-8","u":"Prise en charge","t":"Connaître les principes de la prescription médicamenteuse, les modalités de surveillance et d’arrêt","q":"Quels sont les principes fondamentaux de la prescription médicamenteuse abordés dans le cadre d'une décision thérapeutique personnalisée ?","a":"<p>Les principes fondamentaux de la prescription médicamenteuse incluent :</p><ul><li>Une <strong>indication validée</strong>.</li><li>Une évaluation de la <strong>balance bénéfice/risque</strong> pour le patient.</li><li>Le <strong>respect de l'Autorisation de Mise sur le Marché (AMM)</strong> et du <strong>Résumé des Caractéristiques du Produit (RCP)</strong>.</li></ul>"},{"i":"fb9666115750","n":322,"o":"322-8","u":"Prise en charge","t":"Connaître les principes de la prescription médicamenteuse, les modalités de surveillance et d’arrêt","q":"Quelles sont les modalités d'arrêt d'un traitement médicamenteux, notamment en fonction du risque de rebond ou de sevrage ?","a":"<p>Les modalités d'arrêt d'un traitement médicamenteux comprennent :</p><ul><li>Une <strong>réévaluation régulière</strong> de la pertinence du traitement.</li><li>La <strong>déprescription</strong> si le traitement n'est plus justifié.</li><li>Un <strong>arrêt progressif</strong> si un risque de phénomène de rebond ou de syndrome de sevrage est présent.</li></ul>"},{"i":"2e1afd043e51","n":322,"o":"322-9","u":"Prise en charge","t":"Connaître les principes de la consultation pré-anesthésique","q":"Quels sont les trois critères déterminant la prescription d'un bilan pré-interventionnel personnalisé en consultation pré-anesthésique ?","a":"<ul><li>Le <strong>type de geste</strong> envisagé.</li><li>Le <strong>risque hémorragique</strong> lié au geste et au patient.</li><li>Les <strong>antécédents</strong> et les <strong>traitements</strong> du patient.</li></ul>"},{"i":"3488c8abaff9","n":322,"o":"322-9","u":"Prise en charge","t":"Connaître les principes de la consultation pré-anesthésique","q":"Quel est le principe général concernant la prescription des examens complémentaires avant un geste invasif ou chirurgical nécessitant une anesthésie ?","a":"<p>Aucun examen complémentaire n'est <strong>systématique</strong> avant un geste invasif ou chirurgical, avec ou sans anesthésie générale. La prescription d'un bilan pré-interventionnel doit être <strong>raisonnée, rationnelle et individualisée</strong>.</p>"},{"i":"5d8e02e43a55","n":322,"o":"322-9","u":"Prise en charge","t":"Connaître les principes de la consultation pré-anesthésique","q":"Dans quel exemple précis (type de patient et de geste) n'est-il pas nécessaire de réaliser d'examens complémentaires en consultation pré-anesthésique ?","a":"<p>Un geste à <strong>faible risque hémorragique</strong> chez un patient <strong>jeune</strong>, sans traitement interférant avec l'hémostase et sans diathèse hémorragique personnelle ou familiale, ne nécessite aucun examen complémentaire.</p>"}]};